INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Bedrohungssoftware immer ein Virus auf dem Gerät installiert?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch nur Daten stehlen oder Geld fordern"}, {"text": "Ja", "correct": false, "because": "Nicht immer ein Virus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutzen Angreifer primär, um Nutzer zu täuschen?', 3, '[{"text": "Social Engineering", "correct": true, "because": "Nutzt Angst und Täuschung"}, {"text": "SQL-Injection", "correct": false, "because": "Für Datenbanken"}, {"text": "Brute Force", "correct": false, "because": "Für Passwörter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anzeichen deuten auf eine Bedrohung durch solche Software hin?', 5, '[{"text": "Ungewöhnliche Pop-ups", "correct": true, "because": "Typisch für Angriffe"}, {"text": "Dringende Warnungen", "correct": true, "because": "Erzeugen Panik"}, {"text": "Schnelle Downloads", "correct": false, "because": "Nicht spezifisch"}, {"text": "Hohe CPU-Auslastung", "correct": false, "because": "Nicht immer erkennbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bedrohungssoftware imitiert oft Antivirenprogramme. b) Sie ist immer kostenlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft kostenpflichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abwehr solcher Bedrohungen?', 4, '[{"text": "Antivirensoftware", "correct": false, "because": "Schützt vor Malware"}, {"text": "Pop-up-Blocker", "correct": false, "because": "Verhindert Warnungen"}, {"text": "Farbschema", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Software immer per E-Mail verteilt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch über Pop-ups oder Websites"}, {"text": "Ja", "correct": false, "because": "Mehrere Verbreitungswege"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik hilft, solche Bedrohungen zu erkennen?', 4, '[{"text": "Überprüfung der Quelle", "correct": true, "because": "Zeigt Täuschung"}, {"text": "Schnelles Klicken", "correct": false, "because": "Erhöht Risiko"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Software immer harmlos ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann Daten stehlen oder Malware installieren"}, {"text": "Ja", "correct": false, "because": "Oft schädlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Installiert solche Software immer Ransomware?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch andere Malware sein"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Ransomware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen vor solchen Bedrohungen?', 5, '[{"text": "Antivirus-Updates", "correct": true, "because": "Erkennt Malware"}, {"text": "Pop-up-Blocker", "correct": true, "because": "Stoppt Warnungen"}, {"text": "Hohe Bildschirmauflösung", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Schnelle CPU", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei einem verdächtigen Pop-up priorisieren?', 4, '[{"text": "Browser schließen", "correct": true, "because": "Verhindert Interaktion"}, {"text": "Klick auf Lösung", "correct": false, "because": "Risiko für Malware"}, {"text": "Neustart", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bedrohungssoftware nutzt Angst. b) Sie ist immer leicht erkennbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft täuschend echt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um mich vor solchen Angriffen zu schützen?', 3, '[{"text": "Firewall", "correct": false, "because": "Blockiert Bedrohungen"}, {"text": "Browser-Updates", "correct": false, "because": "Schließen Lücken"}, {"text": "Bildschirmschoner", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich auf eine verdächtige Warnung reagiere?', 4, '[{"text": "Nicht klicken, scan ausführen", "correct": true, "because": "Vermeidet Malware"}, {"text": "Sofort kaufen", "correct": false, "because": "Risiko für Betrug"}, {"text": "Pop-up ignorieren", "correct": false, "because": "Kann aktiv bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Software nur Windows betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch macOS, Android betroffen"}, {"text": "Ja", "correct": false, "because": "Plattformübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten vermeidet solche Bedrohungen?', 3, '[{"text": "Links prüfen", "correct": true, "because": "Verhindert Betrug"}, {"text": "Alle Pop-ups klicken", "correct": false, "because": "Erhöht Risiko"}, {"text": "Antivirus deaktivieren", "correct": false, "because": "Gefährdet System"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist jede Warnung im Browser gefährlich?', 2, '[{"text": "Nein", "correct": true, "because": "Nur verdächtige sind riskant"}, {"text": "Ja", "correct": false, "because": "Echte Warnungen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien helfen, solche Angriffe zu blockieren?', 5, '[{"text": "Antivirensoftware", "correct": true, "because": "Erkennt Malware"}, {"text": "Pop-up-Blocker", "correct": true, "because": "Verhindert Warnungen"}, {"text": "Grafikkarte", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Hoher RAM", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abwehr solcher Bedrohungen unwichtig?', 3, '[{"text": "Software-Updates", "correct": false, "because": "Schließen Lücken"}, {"text": "Firewall", "correct": false, "because": "Schützt Netzwerk"}, {"text": "Tastaturlayout", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine verdächtige Warnung sehe?', 4, '[{"text": "Browser schließen, Antivirus prüfen", "correct": true, "because": "Sichert System"}, {"text": "Sofort klicken", "correct": false, "because": "Risiko für Malware"}, {"text": "Computer ausschalten", "correct": false, "because": "Nicht immer nötig"}]');
